/**
 * Row actions must behave identically for pointer, Enter and Space activation.
 * Run with npm run test:editable-table-menu -w @verbb/plugin-kit-playground.
 * TEST_BUILT=1 exercises the distribution generated by npm run build:web.
 */
import assert from 'node:assert/strict';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';
import { createServer } from 'vite';

const playground = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const repo = path.dirname(playground);
const built = process.env.TEST_BUILT === '1';
const server = await createServer({
    configFile: false,
    root: playground,
    logLevel: 'error',
    server: { host: '127.0.0.1', port: 0, fs: { allow: [repo] } },
    optimizeDeps: { entries: ['tests/editable-table-menu.html'] },
    resolve: {
        alias: [{
            find: /^@verbb\/plugin-kit-web\/components\/(.+)\.js$/,
            replacement: `${repo}/plugin-kit-web/${built ? 'dist' : 'src'}/components/$1.${built ? 'js' : 'ts'}`,
        }],
    },
});
let browser;
let failures = 0;
let passed = 0;
try {
    await server.listen();
    browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();
    page.setDefaultTimeout(5000);
    const errors = [];
    page.on('pageerror', (error) => errors.push(error.message));
    await page.goto(`${server.resolvedUrls.local[0]}tests/editable-table-menu.html`);
    await page.locator('body[data-ready="true"]').waitFor();

    const table = page.locator('#table');
    const output = (id) => page.locator(`#${id}`).textContent();
    const reset = async (options) => {
        await page.reload();
        await page.locator('body[data-ready="true"]').waitFor();
        await page.evaluate((options) => window.resetFixture(options), options);
    };
    const menuAt = (rowIndex) => table.locator('pk-dropdown-menu').nth(rowIndex);
    const triggerAt = (rowIndex) => menuAt(rowIndex).getByRole('button', { name: 'Row actions' });

    const waitForMenuFocus = () => page.waitForFunction(() => {
        let active = document.activeElement;
        while (active) {
            if (active.localName === 'pk-dropdown-item') return true;
            active = active.shadowRoot?.activeElement;
        }
        return false;
    });

    async function activate(label, method, rowIndex = 1) {
        const menu = menuAt(rowIndex);
        const trigger = triggerAt(rowIndex);
        if (method === 'pointer') {
            await trigger.click();
            await menu.locator('pk-dropdown-item').filter({ hasText: new RegExp(`^\\s*${label}\\s*$`) }).click();
        } else {
            await trigger.press('ArrowDown');
            await waitForMenuFocus();
            const enabled = menu.locator('pk-dropdown-item:not([disabled])');
            const labels = (await enabled.allTextContents()).map((text) => text.trim());
            const index = labels.indexOf(label);
            assert.ok(index >= 0, `${label} must be enabled`);
            for (let i = 0; i < index; i++) await page.keyboard.press('ArrowDown');
            await page.keyboard.press(method);
        }
        await page.waitForFunction(() => [...document.querySelector('#table').shadowRoot.querySelectorAll('pk-dropdown-menu')].every((menu) => !menu.open));
    }

    async function check(name, run) {
        try {
            await reset();
            await run();
            passed++;
            console.log(`PASS ${name}`);
        } catch (error) {
            failures++;
            console.error(`FAIL ${name}: ${error.message}`);
            await page.keyboard.press('Escape');
        }
    }

    const cases = [
        ['Insert above', 'Alpha|New|Beta|Gamma'],
        ['Insert below', 'Alpha|Beta|New|Gamma'],
        ['Move up', 'Beta|Alpha|Gamma'],
        ['Move down', 'Alpha|Gamma|Beta'],
    ];
    for (const method of ['Enter', 'Space', 'pointer']) {
        for (const [label, expected] of cases) {
            await check(`${method}: ${label}`, async () => {
                await activate(label, method);
                assert.equal(await output('row-order'), expected);
                assert.equal(await output('change-count'), '1', 'one change per activation');
                assert.equal(await output('action-count'), '0');
                const movedIndex = expected.split('|').indexOf('Beta');
                assert.equal(await triggerAt(movedIndex).evaluate((el) => {
                    let active = document.activeElement;
                    while (active?.shadowRoot?.activeElement) active = active.shadowRoot.activeElement;
                    return active === el;
                }), true, 'focus follows the original row after insertion or movement');
            });
        }
        for (const [label, action] of [['Inspect', 'inspect'], ['Mark reviewed', 'review']]) {
            await check(`${method}: custom ${action}`, async () => {
                await activate(label, method);
                assert.equal(await output('action-count'), '1', 'one custom event per activation');
                assert.deepEqual(JSON.parse(await output('last-action')), { action, rowIndex: 1, name: 'Beta' });
                assert.equal(await output('change-count'), '0');
                assert.equal(await output('row-order'), 'Alpha|Beta|Gamma');
                if (action === 'review') {
                    assert.equal(await menuAt(1).locator('pk-dropdown-item[value="review"]').getAttribute('checked'), '');
                }
                assert.equal(await triggerAt(1).evaluate((el) => {
                    let active = document.activeElement;
                    while (active?.shadowRoot?.activeElement) active = active.shadowRoot.activeElement;
                    return active === el;
                }), true, 'focus returns to the row action trigger');
            });
        }
    }
    await check('disabled actions and row limits', async () => {
        await reset({ maxRows: 3 });
        await triggerAt(0).press('ArrowDown');
        await waitForMenuFocus();
        const menu = menuAt(0);
        for (const label of ['Locked', 'Insert above', 'Insert below', 'Move up']) {
            assert.notEqual(await menu.locator('pk-dropdown-item').filter({ hasText: new RegExp(`^\\s*${label}\\s*$`) }).getAttribute('disabled'), null);
        }
        // Arrow navigation skips disabled custom, insert and boundary actions.
        await page.keyboard.press('ArrowDown');
        await page.keyboard.press('ArrowDown');
        await page.keyboard.press('Enter');
        assert.equal(await output('row-order'), 'Beta|Alpha|Gamma');
        assert.equal(await output('change-count'), '1');
        assert.equal(await output('action-count'), '0');
    });
    await check('disabled table blocks row actions', async () => {
        await reset({ disabled: true });
        assert.equal(await triggerAt(1).isDisabled(), true);
        assert.equal(await output('change-count'), '0');
        assert.equal(await output('action-count'), '0');
    });
    assert.deepEqual(errors, [], 'no browser exceptions');
    console.log(`${passed} passed, ${failures} failed (${built ? 'built package' : 'source'})`);
    process.exitCode = failures ? 1 : 0;
} finally {
    await browser?.close();
    await server.close();
}
